function buildMap(pairs: [string, number][]): Map<string, number> {
  const map = new Map<string, number>();
  for (const [name, price] of pairs) {
    map.set(name, price);
  }
  return map;
}

function lookup(map: Map<string, number>, key: string): number {
  if (map.has(key)) {
    return map.get(key);
  }
  return -1;
}

