answer_code:
function shiftLetters(text: string, shift: number): string {
  const a = "a".charCodeAt(0);
  const z = "z".charCodeAt(0);
  let result = "";
  for (const ch of text) {
    const code = ch.charCodeAt(0);
    if (code >= a && code <= z) {
      result += String.fromCharCode(a + ((code - a + shift) % 26));
    } else {
      result += ch;
    }
  }
  return result;
}

