class Temperature {
  celsius: number;

  constructor(celsius: number) {
    this.celsius = celsius;
  }

  toFahrenheit(): number {
    return this.celsius * 9 / 5 + 32;
  }

  static fromFahrenheit(fahrenheit: number): Temperature {
    return new Temperature((fahrenheit - 32) * 5 / 9);
  }
}

