type Fruit = "apple" | "banana" | "orange";

type Prices = Record<Fruit, number>;

function totalPrice(prices: Prices, order: Fruit[]): number {
  let total = 0;
  for (const fruit of order) {
    total += prices[fruit];
  }
  return total;
}

