type Rgb = [number, number, number];
type Palette = Record<string, Rgb>;

const palette = {
  red: [255, 0, 0],
  green: [0, 128, 0],
  blue: [0, 0, 255],
} satisfies Palette;

type ColorName = keyof typeof palette;

function brightness(name: ColorName): number {
  const [r, g, b] = palette[name];
  return Math.round((r + g + b) / 3);
}
